def ball(game, screen):
    rows = screen.rows
    game.check(len(rows) == 3, 'The board must have 3 rows.')
    cells = [
        (r, c)
        for r, row in enumerate(rows)
        for c, cell in enumerate(row)
        if cell == 'O'
    ]
    game.check(len(cells) == 1, 'The board must show exactly one O.')
    return cells[0]


def check(game):
    before = ball(game, game.screen())
    after = ball(game, game.send('l'))
    game.check(
        after[1] == before[1] - 1,
        'Pressing l must move the O one column left.',
    )
